import React, { useState } from "react";
import { FaMoon, FaSun, FaSearch, FaUser, FaShoppingCart } from "react-icons/fa";
import logo from "../../assets/imgs/inicio/logo.png";
import SearchBar from "./SearchBar";

const Header = () => {
  const [darkMode, setDarkMode] = useState(false);
  const [profileMenu, setProfileMenu] = useState("");

  const toggleDarkMode = () => {
    setDarkMode((prevMode) => !prevMode);
    document.documentElement.classList.toggle("dark");
  };

  const toggleProfileMenu = () => {
    setProfileMenu((prev) => !prev)
  }

  const closeMenu = (event) => {
    }

  return (
    <header className="flex items-center justify-between p-4 bg-primary dark:bg-nba-blue shadow-md">
      {/* Logo */}
      <div>
        <img src={logo} alt="BSKT Store Logo" className="h-14"/>
      </div>

      {/* Barra de Pesquisa */}
        <SearchBar />

      <div className="flex items-center space-x-4">
        <button
          id="menu-button"
          aria-expanded="true"
          aria-haspopup="true"
        >
          <FaUser className="text-gray-600 dark:text-gray-300 text-xl cursor-pointer" />
        </button>
        <FaShoppingCart className="text-gray-600 dark:text-gray-300 text-xl cursor-pointer" />
        <button
          onClick={toggleDarkMode}
          className="text-gray-600 dark:text-gray-300 text-xl"
        >
          {darkMode ? <FaSun /> : <FaMoon />}
        </button>
      </div>

      <div class="absolute right-0 z-10 mt-2 w-56 origin-top-right rounded-md bg-white shadow-lg ring-1 ring-black/5 focus:outline-none" role="menu" aria-orientation="vertical" aria-labelledby="menu-button" tabindex="-1">
          <div class="py-1" role="none">
            <a href="#" class="block px-4 py-2 text-sm text-gray-700" role="menuitem" tabindex="-1" id="menu-item-0">Account settings</a>
            <a href="#" class="block px-4 py-2 text-sm text-gray-700" role="menuitem" tabindex="-1" id="menu-item-1">Support</a>
            <a href="#" class="block px-4 py-2 text-sm text-gray-700" role="menuitem" tabindex="-1" id="menu-item-2">License</a>
            <form method="POST" action="#" role="none">
              <button type="submit" class="block w-full px-4 py-2 text-left text-sm text-gray-700" role="menuitem" tabindex="-1" id="menu-item-3">Sign out</button>
            </form>
          </div>
        </div>
    </header>
  );
};

export default Header;
